return [{ json: { date: dateOnly } }];

const weights = {
  1: 1,
  2: 1,
  3: 1,
  4: 1,
  5: 1,
  6: 1,

};

const pool = [];

for (const num in weights) {
  for (let i = 0; i < weights[num]; i++) {
    pool.push(Number(num));
  }
}

const randomNumber = pool[Math.floor(Math.random() * pool.length)];

return [{ json: { randomNumber } }];

