import json

items = _input.all()
data = items[0].json

# Step 1: Get raw output string
text = data.get("output", "")

if not text:
    return {
        "error": "No output field found",
        "raw_response": data
    }

# Step 2: Remove markdown wrappers
text = text.strip()

if text.startswith("```"):
    text = text.replace("```json", "").replace("```", "").strip()

# Step 3: Parse JSON
try:
    parsed = json.loads(text)
except Exception as e:
    return {
        "error": "Invalid JSON format",
        "raw_output": text,
        "exception": str(e)
    }

# Step 4: Return exact structured JSON
return parsed
